import time
from google.api_core import exceptions

def robust_hair_transformation(target_image, reference_images, max_retries=3):
    """Robusztus hajátalakítás retry logikával"""

    for attempt in range(max_retries):
        try:
            response = client.models.generate_content(
                model='gemini-3-pro-image-preview',
                contents=[ultimate_prompt] + reference_images + [target_image],
                config=config
            )

            # Ellenőrizd, hogy van-e generated image
            has_image = any(
                part.inline_data is not None 
                for part in response.parts 
                if not part.thought
            )

            if has_image:
                return response
            else:
                print(f"Attempt {attempt+1}: No image generated, retrying...")

        except exceptions.ResourceExhausted:
            print(f"Rate limit hit, waiting 60s...")
            time.sleep(60)

        except exceptions.InvalidArgument as e:
            print(f"Invalid argument: {e}")
            # Esetleg csökkentsd a felbontást vagy módosítsd a promptot
            if "imageSize" in str(e):
                config.image_config.image_size = "2K"
                print("Reduced to 2K, retrying...")

        except Exception as e:
            print(f"Unexpected error: {e}")
            time.sleep(10)

    raise Exception("Failed after all retries")

